const VERIFY = /terms not stated|free with attribution|free with citation|Metro Transit licence|operator terms|county disclaimer|511 terms|OpenFEMA terms|EPA terms/i;
const NO = /non-commercial|NC|forbidden|no storing|paid|restricted|discontinued|counts only|not queryable|hijacked|—$/;
let REGX = null;  // built on first use: REG is declared further down (generated block)
function audit(n) { if (!n) return null; REGX = REGX || REG.map(([p, v, a, why, id]) => [new RegExp(p), v, a, why, id]); for (const x of REGX) if (x[0].test(n)) return x; return null; }
function commercial(lic, st, n) {
  const a = audit(n);
  if (a && a[1] === "red") return ["no", "not allowed (licence audit)"];
  if (a && a[1] === "grey") return ["verify", "Excluded — licence audit"];
  if (a && a[1] === "green" && st !== "no") return ["ok", "OK · licence audit"];
  if (st === "no" || NO.test(lic)) return ["no", "not allowed / unavailable"];
  if (VERIFY.test(lic)) return ["verify", "Excluded — terms not explicit"];
  if (/share-alike|ODbL|CC-BY-SA/i.test(lic)) return ["ok", "OK · share-alike"];
  if (/CC-BY|attribution|Copernicus|CDLA/i.test(lic)) return ["ok", "OK · attribution"];
  if (/public domain|CC0|public$|^open$/i.test(lic)) return ["ok", "OK"];
  return ["verify", "Excluded — terms not explicit"];
}
